def find_topmost_carpet(n, carpets, point):
    """
    Finds the topmost carpet covering a given point on the coordinate plane.

    Args:
        n (int): The total number of carpets.
        carpets (list of tuples): A list containing n tuples, each representing a carpet's information.
                                  Each tuple contains four integers (a, b, g, k) where (a, b) is the
                                  coordinates of the bottom-left corner of the carpet and (g, k) are
                                  the lengths of the carpet along the x and y axis respectively.
        point (tuple): A tuple containing two integers (x, y), the coordinates of the point to check.

    Returns:
        int: The number of the topmost carpet covering the point (x, y), or -1 if no carpet covers it.
    """
    def is_point_in_carpet(carpet, point):
        a, b, g, k = carpet
        return a <= point[0] < a + g and b <= point[1] < b + k

    def find_topmost_carpet_helper(carpets, point, visited):
        if not carpets:
            return -1
        topmost = -1
        for i, carpet in enumerate(carpets):
            if is_point_in_carpet(carpet, point) and not visited[i]:
                visited[i] = True
                topmost = i
                break
        if topmost == -1:
            return -1
        for i, carpet in enumerate(carpets):
            if is_point_in_carpet(carpet, point) and not visited[i] and i != topmost:
                visited[i] = True
                temp = find_topmost_carpet_helper(carpets, point, visited)
                if temp != -1:
                    topmost = temp
        return topmost

    visited = [False for _ in range(n)]
    return find_topmost_carpet_helper(carpets, point, visited)

def max_value_on_paths(N, grid_values):
    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    for x, y, value in grid_values:
        dp[x][y] = [value, value]

    for i in range(N-2, -1, -1):
        for j in range(N-2, -1, -1):
            if i == N-1 and j == N-1:
                continue
            dp[i][j] = [
                max(dp[i+1][j][0], dp[i+1][j][1], dp[i][j+1][0] + dp[i+1][j][1]),
                max(dp[i+1][j][0], dp[i+1][j][1], dp[i][j+1][1] + dp[i+1][j][0])
            ]

    return max(dp[0][0][0], dp[0][0][1])

