def max_product(num_str, N, K):
    nums = list(map(int, num_str))
    dp = [[0] * (N + 1) for _ in range(K + 1)]
    for i in range(N):
        for j in range(K + 1):
            if j == 0:
                dp[j][i] = 1
            else:
                dp[j][i] = max(dp[j - 1][i - 1] * nums[i], dp[j][i - 1])
    return dp[K][N - 1]

