def polynomial_to_string(n, coeffs):
    result = ""
    for i in range(len(coeffs)):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        term = ""
        if coeff != 1 or i == 0:
            term += str(abs(coeff))
        if i > 0:
            term += "x"
            if i > 1:
                term += "^" + str(i)
        if coeff < 0:
            term = "-" + term
        result += term
        if i < len(coeffs) - 1:
            result += "+"
    return result

