def decode(encoded, original, message):
    if len(set(encoded)) != len(set(original)):
        return "Failed"
    if set(encoded) != set(message):
        return "Failed"
    mapping = {x: y for x, y in zip(encoded, original)}
    decoded = [mapping.get(i) for i in message]
    if any(i is None for i in decoded):
        return "Failed"
    return "".join(decoded)

def count_sequences(n, last, memo):
    if n == 0:
        return 1
    if n < 0 or last < n:
        return 0
    if last in memo:
        return memo[last]
    total = 0
    for i in range(n, last//2+1):
        total += count_sequences(i, i, memo)
    memo[last] = total
    return total

