def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 1
    increasing = heights[0] >= heights[1]
    for i in range(2, n):
        if heights[i] < heights[i-1]:
            increasing = not increasing
        if increasing and heights[i-1] < heights[i] or not increasing and heights[i-1] > heights[i]:
            return i
    return n

